package id.ufal.localnhread;
import android.graphics.Bitmap; import android.view.*; import android.widget.ImageView; import androidx.annotation.NonNull; import androidx.recyclerview.widget.RecyclerView; import java.util.*;
final class PreviewAdapter extends RecyclerView.Adapter<PreviewAdapter.Holder>{interface Click{void open(int page);} private final List<Bitmap> images;private final Click click;PreviewAdapter(List<Bitmap> images,Click click){this.images=images;this.click=click;}@NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_preview,p,false));}public void onBindViewHolder(@NonNull Holder h,int p){h.image.setImageBitmap(images.get(p));h.itemView.setOnClickListener(v->click.open(p));}public int getItemCount(){return images.size();}static final class Holder extends RecyclerView.ViewHolder{final ImageView image;Holder(View v){super(v);image=v.findViewById(R.id.previewImage);}}}
